package bench.app;
import android.app.Activity;import android.os.Bundle;import android.widget.*;import android.view.View;import java.util.*;import java.time.LocalDate;
public class MainActivity extends Activity {
 List<TrackerModel.Entry> entries;LinearLayout root,list,rows,form,detail;EditText title,date,sets,reps,day;TextView summary,error,detailTitle,detailVolume;String editing=null,selected=null;
 @Override public void onCreate(Bundle b){super.onCreate(b);entries=TrackerModel.read(getSharedPreferences("tracker",0).getString("state","[]"));root=panel(null,"root");root.setPadding(24,48,24,24);setContentView(root);list=panel(root,"list");day=input(list,"day","조회 날짜");day.setText(LocalDate.now().toString());summary=text(list,"summary");button(list,"new","새 운동").setOnClickListener(v->edit(null));ScrollView scroll=new ScrollView(this);rows=panel(null,"rows");scroll.addView(rows);list.addView(scroll);
 form=panel(root,"form");title=input(form,"title","운동 이름");date=input(form,"date","YYYY-MM-DD");sets=input(form,"sets","세트");reps=input(form,"reps","횟수");sets.setInputType(2);reps.setInputType(2);error=text(form,"error");button(form,"save","저장").setOnClickListener(v->save());button(form,"cancel","취소").setOnClickListener(v->show(list));
 detail=panel(root,"detail");detailTitle=text(detail,"detail-title");detailVolume=text(detail,"detail-volume");button(detail,"edit","수정").setOnClickListener(v->edit(selected));button(detail,"delete","삭제").setOnClickListener(v->{entries=TrackerModel.delete(entries,selected);persist();render();show(list);});button(detail,"back","목록").setOnClickListener(v->{render();show(list);});day.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){render();}public void afterTextChanged(android.text.Editable e){}});render();show(list);}
 LinearLayout panel(LinearLayout parent,String tag){LinearLayout v=new LinearLayout(this);v.setOrientation(1);v.setTag(tag);if(parent!=null)parent.addView(v);return v;}
 EditText input(LinearLayout p,String tag,String hint){EditText v=new EditText(this);v.setTag(tag);v.setHint(hint);v.setSingleLine(true);p.addView(v);return v;}
 TextView text(LinearLayout p,String tag){TextView v=new TextView(this);v.setTag(tag);p.addView(v);return v;}
 Button button(LinearLayout p,String tag,String title){Button v=new Button(this);v.setTag(tag);v.setText(title);p.addView(v);return v;}
 void show(LinearLayout p){list.setVisibility(p==list?View.VISIBLE:View.GONE);form.setVisibility(p==form?View.VISIBLE:View.GONE);detail.setVisibility(p==detail?View.VISIBLE:View.GONE);}
 TrackerModel.Entry find(String id){for(TrackerModel.Entry e:entries)if(e.id.equals(id))return e;return null;}
 void edit(String id){editing=id;TrackerModel.Entry e=id==null?null:find(id);title.setText(e==null?"":e.title);date.setText(e==null?day.getText():e.date);sets.setText(e==null?"":String.valueOf(e.sets));reps.setText(e==null?"":String.valueOf(e.reps));error.setText("");show(form);}
 void save(){try{String name=title.getText().toString(),d=date.getText().toString();int s=Integer.parseInt(sets.getText().toString()),r=Integer.parseInt(reps.getText().toString());boolean wasEdit=editing!=null;entries=wasEdit?TrackerModel.update(entries,editing,name,d,s,r):TrackerModel.add(entries,name,d,s,r);persist();render();if(wasEdit)open(editing);else show(list);}catch(Exception ex){error.setText("입력 오류");}}
 void open(String id){selected=id;TrackerModel.Entry e=find(id);detailTitle.setText(e.title);detailVolume.setText(String.valueOf(e.sets*e.reps));show(detail);}
 void persist(){getSharedPreferences("tracker",0).edit().putString("state",TrackerModel.write(entries)).commit();}
 void render(){if(rows==null)return;List<TrackerModel.Entry> visible=TrackerModel.select(entries,day.getText().toString());summary.setText(String.valueOf(TrackerModel.volume(visible)));rows.removeAllViews();for(TrackerModel.Entry e:visible){Button b=new Button(this);b.setTag("open:"+e.id);b.setText(e.title);b.setOnClickListener(v->open(e.id));rows.addView(b);}}
}
